retry() { "$@" && return 0; sleep 4; "$@"; }   # in-cluster probes can flake on a loaded laptop
check "StorageClass kv-local: local-path, Delete, WaitForFirstConsumer, volume expansion allowed" bash -c "[ \"\$(kubectl --context main get sc kv-local -o jsonpath='{.provisioner} {.reclaimPolicy} {.volumeBindingMode} {.allowVolumeExpansion}')\" = 'rancher.io/local-path Delete WaitForFirstConsumer true' ]"
check "headless Service kv (port 6379) and StatefulSet kv with 3 ready replicas" bash -c "[ \"\$(kubectl --context main -n kv get svc kv -o jsonpath='{.spec.clusterIP} {.spec.ports[0].port}')\" = 'None 6379' ] && [ \"\$(kubectl --context main -n kv get sts kv -o jsonpath='{.spec.serviceName} {.status.readyReplicas}')\" = 'kv 3' ]"
check "PVCs data-kv-0..2 are Bound, 256Mi, class kv-local" bash -c "for i in 0 1 2; do [ \"\$(kubectl --context main -n kv get pvc data-kv-\$i -o jsonpath='{.status.phase} {.spec.storageClassName} {.spec.resources.requests.storage}')\" = 'Bound kv-local 256Mi' ] || exit 1; done"
check "kv-1.kv.kv.svc.cluster.local resolves to pod kv-1" retry bash -c "ip=\$(kubectl --context main -n kv get pod kv-1 -o jsonpath='{.status.podIP}'); [ -n \"\$ip\" ] && kubectl --context main -n kv run chk-\$RANDOM --image=$IMG_BUSYBOX --restart=Never --rm -i --quiet -- nslookup kv-1.kv.kv.svc.cluster.local 2>/dev/null | grep -q \"\$ip\""
